// Lumenweave: Prism Warden — generated offline bundle (game/src/*.js).
// No network requests: every asset is drawn or synthesised at runtime.
(function () {
'use strict';

// ---- types.js ----

// types.js — shared shapes for Lumenweave: Prism Warden.
// Written as JSDoc typedefs so the file stays valid JavaScript: the bundle
// builder concatenates it verbatim, and editors still get type checking.

/**
 * @typedef {Object} Vec
 * @property {number} x
 * @property {number} y
 */

/**
 * @typedef {Object} BeamSegment
 * @property {number} x1 - segment start x
 * @property {number} y1 - segment start y
 * @property {number} x2 - segment end x
 * @property {number} y2 - segment end y
 * @property {number} phase - chromatic phase: 0 cyan, 1 amber, 2 magenta
 * @property {number} depth - bounce depth (0 = direct beam)
 */

/**
 * @typedef {Object} Prism
 * @property {number} x
 * @property {number} y
 * @property {number} angle - slow spin for the facet animation
 * @property {number} placedAt - game time when placed (oldest is replaced)
 * @property {number} flash - 0..1 glow pulse after a beam passes through
 */

/**
 * @typedef {Object} Enemy
 * @property {string} kind - mote | crawler | sentinel | weaver | juggernaut | leviathan
 * @property {number} x
 * @property {number} y
 * @property {number} vx
 * @property {number} vy
 * @property {number} hp
 * @property {number} maxHp
 * @property {number} r - collision radius
 * @property {number} speed
 * @property {number} score - base score on kill
 * @property {number} facing - movement heading in radians
 * @property {number} slowUntil - game time until the slow effect ends
 * @property {number} burnUntil - game time until the amber burn ends
 * @property {number} burnDps
 * @property {number} flash - 0..1 white hit flash
 * @property {number} t - age in seconds
 * @property {number} teleportIn - seconds until the next teleport (weavers)
 * @property {number} shotIn - seconds until the next void orb (weavers)
 * @property {number} wobble - per-enemy wobble phase (motes)
 */

/**
 * @typedef {Object} Particle
 * @property {number} x
 * @property {number} y
 * @property {number} vx
 * @property {number} vy
 * @property {number} life
 * @property {number} maxLife
 * @property {number} size
 * @property {string} color
 * @property {number} shape - 0 dot, 1 shard triangle, 2 ring
 * @property {number} rot
 * @property {number} vr
 */

/**
 * @typedef {Object} FloatText
 * @property {number} x
 * @property {number} y
 * @property {string} text
 * @property {string} color
 * @property {number} life
 * @property {number} size
 */

/**
 * @typedef {Object} Bolt
 * @property {number} x
 * @property {number} y
 * @property {number} vx
 * @property {number} vy
 * @property {number} life
 */

/**
 * @typedef {Object} Orb
 * @property {number} x
 * @property {number} y
 * @property {number} vx
 * @property {number} vy
 * @property {number} r
 * @property {number} life
 */

/**
 * @typedef {Object} BossNode
 * @property {number} seg - which serpent segment the node rides on
 * @property {number} hp
 * @property {number} maxHp
 * @property {boolean} dead
 */


// ---- constants.js ----

// constants.js — arena size, palette, and every tuning number for the game.
// One place to tune: nothing else in the codebase hard-codes a balance value.

const W = 1280;
const H = 720;
const CX = 640; // arena centre x — the Chrono-Astrolabe Core sits here
const CY = 360; // arena centre y
const CORE_R = 46;
const ARENA_R = 330; // soft play-field radius; enemies spawn outside it

// Palette — obsidian-indigo night, brass astrolabe, tri-chromatic light.
const COL = {
  bg: '#070913',
  bg2: '#0b0f24',
  brass: '#c89d54',
  brassDim: 'rgba(200,157,84,0.35)',
  ink: '#e8ecff',
  dim: '#8b93b8',
  cyan: '#35e0ff',
  amber: '#ffb347',
  magenta: '#ff4fd8',
  core: '#ffe9a8',
  danger: '#ff5470',
  good: '#7dffb0',
};

// Chromatic phases, in bounce order: each prism bounce shifts the phase.
const PHASES = [
  { name: 'Cyan', color: COL.cyan, slow: 0.6, burn: 0, arc: 0 },
  { name: 'Amber', color: COL.amber, slow: 1, burn: 9, arc: 0 },
  { name: 'Magenta', color: COL.magenta, slow: 1, burn: 0, arc: 2 },
];

// Player (the Aether Loom).
const PLAYER = {
  r: 16,
  accel: 1500,
  maxSpeed: 340,
  damping: 3.2,
  hullMax: 100,
  hullRegen: 7,
  boltDmg: 14,
  boltSpeed: 920,
  boltCooldown: 0.16,
  boltEnergy: 3,
  beamDps: 46,
  beamDrain: 26, // aether per second while channelling
  beamRange: 760,
  energyMax: 100,
  energyRecharge: 20,
  dashCooldown: 2.4,
  dashSpeed: 980,
  dashTime: 0.16,
  dashIframes: 0.38,
  dashPulseR: 160,
  dashPulseDmg: 18,
};

// Prisms.
const PRISM = {
  max: 3,
  r: 15,
  chainRange: 300, // a refracted beam can hop to a prism this close
  splitAngle: 0.5, // radians either side of the incoming beam
  maxDepth: 3,
};

// Core.
const CORE = { hpMax: 100 };

// Scoring.
const COMBO_STEP = 4; // every 4 chained kills raises the multiplier by 1
const COMBO_MAX = 16;
const RESONANCE_PER_KILL = 8; // percent of Harmonic Resonance per shard

// Boss — THE ECLIPSE LEVIATHAN.
const BOSS = {
  hp: 1500,
  segments: 7,
  orbitR: 300,
  orbitSpeed: 0.32, // radians per second around the core
  nodeHp: 130,
  nodeDmg: 160, // damage to the boss when a node shatters
  flareEvery: 11,
  flareTelegraph: 1.3,
  flareSweep: 2.2,
  spawnEvery: 8,
};


// ---- math-utils.js ----

// math-utils.js — small pure helpers: clamping, angles, a seeded RNG, and
// the segment geometry the refraction code and the hit tests share.

// Seeded RNG (mulberry32) — deterministic when the URL carries ?seed=, so
// screenshot mode renders identically on every run.
function mulberry32(seed) {
  let a = seed >>> 0;
  return function next() {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// The game's live RNG. Engine reseeds it at boot (from ?seed= or the clock).
let rng = mulberry32(1);

function rand(a, b) {
  return a + rng() * (b - a);
}

function randInt(a, b) {
  return Math.floor(rand(a, b + 1));
}

function pick(arr) {
  return arr[Math.floor(rng() * arr.length)];
}

function clamp(v, lo, hi) {
  return v < lo ? lo : v > hi ? hi : v;
}

function lerp(a, b, t) {
  return a + (b - a) * t;
}

function dist2(ax, ay, bx, by) {
  const dx = bx - ax;
  const dy = by - ay;
  return dx * dx + dy * dy;
}

function dist(ax, ay, bx, by) {
  return Math.sqrt(dist2(ax, ay, bx, by));
}

// Shortest distance from point (px,py) to segment (x1,y1)-(x2,y2).
function segDist(px, py, x1, y1, x2, y2) {
  const dx = x2 - x1;
  const dy = y2 - y1;
  const len2 = dx * dx + dy * dy;
  let t = len2 === 0 ? 0 : ((px - x1) * dx + (py - y1) * dy) / len2;
  t = clamp(t, 0, 1);
  const cx = x1 + t * dx;
  const cy = y1 + t * dy;
  return Math.sqrt(dist2(px, py, cx, cy));
}

// Smallest signed angle from a to b, in (-PI, PI].
function angleDiff(a, b) {
  let d = (b - a) % (Math.PI * 2);
  if (d > Math.PI) d -= Math.PI * 2;
  if (d <= -Math.PI) d += Math.PI * 2;
  return d;
}

// Ray (ox,oy) + t*(dx,dy) against a circle: returns the smallest t >= 0 of
// the hit, or -1 when the ray misses. Used to find the prism a beam hits.
function rayCircle(ox, oy, dx, dy, cx, cy, r) {
  const ex = cx - ox;
  const ey = cy - oy;
  const tca = ex * dx + ey * dy;
  if (tca < 0) return -1;
  const d2 = ex * ex + ey * ey - tca * tca;
  if (d2 > r * r) return -1;
  return tca - Math.sqrt(r * r - d2);
}


// ---- audio.js ----

// audio.js — every sound is synthesised live with the Web Audio API:
// no audio files, no network. The context is created on the first user
// gesture (a click or keypress), as browsers require; M toggles mute.

function AudioEngine() {
  this.ctx = null;
  this.master = null;
  this.muted = false;
  this.droneNodes = null;
  this.beamOsc = null;
  this.beamGain = null;
  this.beamOn = false;
}

// Create (or resume) the context. Safe to call on every gesture.
AudioEngine.prototype.unlock = function () {
  if (!this.ctx) {
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    this.ctx = new AC();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.5;
    this.master.connect(this.ctx.destination);
    this.startDrone();
  }
  if (this.ctx.state === 'suspended') this.ctx.resume();
};

AudioEngine.prototype.setMuted = function (m) {
  this.muted = m;
  if (this.master) this.master.gain.value = m ? 0 : 0.5;
};

// Quiet two-oscillator ambient drone under everything.
AudioEngine.prototype.startDrone = function () {
  const ctx = this.ctx;
  const g = ctx.createGain();
  g.gain.value = 0.045;
  const filt = ctx.createBiquadFilter();
  filt.type = 'lowpass';
  filt.frequency.value = 420;
  const o1 = ctx.createOscillator();
  o1.type = 'sine';
  o1.frequency.value = 55;
  const o2 = ctx.createOscillator();
  o2.type = 'triangle';
  o2.frequency.value = 82.5;
  const lfo = ctx.createOscillator();
  lfo.frequency.value = 0.07;
  const lfoG = ctx.createGain();
  lfoG.gain.value = 0.02;
  lfo.connect(lfoG);
  lfoG.connect(g.gain);
  o1.connect(filt);
  o2.connect(filt);
  filt.connect(g);
  g.connect(this.master);
  o1.start();
  o2.start();
  lfo.start();
  this.droneNodes = { o1, o2, lfo, g };
};

// One short pitched blip with an exponential decay envelope.
AudioEngine.prototype.blip = function (freq, dur, type, vol, slideTo) {
  if (!this.ctx || this.muted) return;
  const ctx = this.ctx;
  const t = ctx.currentTime;
  const o = ctx.createOscillator();
  const g = ctx.createGain();
  o.type = type || 'sine';
  o.frequency.setValueAtTime(freq, t);
  if (slideTo) o.frequency.exponentialRampToValueAtTime(slideTo, t + dur);
  g.gain.setValueAtTime(vol || 0.2, t);
  g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
  o.connect(g);
  g.connect(this.master);
  o.start(t);
  o.stop(t + dur + 0.02);
};

// White-noise burst through a band-pass filter (shatter / whoosh / horn air).
AudioEngine.prototype.noiseBurst = function (dur, freq, vol, q) {
  if (!this.ctx || this.muted) return;
  const ctx = this.ctx;
  const t = ctx.currentTime;
  const len = Math.max(1, Math.floor(ctx.sampleRate * dur));
  const buf = ctx.createBuffer(1, len, ctx.sampleRate);
  const data = buf.getChannelData(0);
  for (let i = 0; i < len; i++) data[i] = (Math.random() * 2 - 1) * (1 - i / len);
  const src = ctx.createBufferSource();
  src.buffer = buf;
  const filt = ctx.createBiquadFilter();
  filt.type = 'bandpass';
  filt.frequency.value = freq || 2400;
  filt.Q.value = q || 1;
  const g = ctx.createGain();
  g.gain.setValueAtTime(vol || 0.25, t);
  g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
  src.connect(filt);
  filt.connect(g);
  g.connect(this.master);
  src.start(t);
};

// Prism-bounce chime: pitch climbs the pentatonic ladder with the combo.
AudioEngine.prototype.chime = function (combo) {
  const scale = [523.25, 587.33, 659.25, 783.99, 880.0, 1046.5];
  const step = Math.min(scale.length - 1, Math.floor(combo / 2));
  this.blip(scale[step], 0.35, 'sine', 0.16);
  this.blip(scale[step] * 2, 0.22, 'triangle', 0.06);
};

AudioEngine.prototype.shoot = function () {
  this.blip(880, 0.09, 'square', 0.07, 440);
};

AudioEngine.prototype.hit = function () {
  this.blip(220, 0.07, 'triangle', 0.12, 140);
};

AudioEngine.prototype.shatter = function () {
  this.noiseBurst(0.4, 3200, 0.3, 0.8);
  this.blip(1567, 0.5, 'sine', 0.14, 784);
  this.blip(2093, 0.4, 'sine', 0.09, 1046);
};

AudioEngine.prototype.dash = function () {
  this.noiseBurst(0.25, 900, 0.22, 1.4);
  this.blip(180, 0.22, 'sawtooth', 0.08, 420);
};

AudioEngine.prototype.horn = function () {
  // Boss warning horn: low saw swell with a fifth above it.
  if (!this.ctx || this.muted) return;
  const ctx = this.ctx;
  const t = ctx.currentTime;
  [110, 164.8].forEach(function (f) {
    const o = ctx.createOscillator();
    const g = ctx.createGain();
    o.type = 'sawtooth';
    o.frequency.value = f;
    g.gain.setValueAtTime(0.0001, t);
    g.gain.linearRampToValueAtTime(0.16, t + 0.35);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 1.4);
    o.connect(g);
    g.connect(this.master);
    o.start(t);
    o.stop(t + 1.5);
  });
};

AudioEngine.prototype.coreHit = function () {
  this.blip(98, 0.4, 'sawtooth', 0.2, 55);
  this.noiseBurst(0.3, 500, 0.2, 1);
};

AudioEngine.prototype.convergence = function () {
  // Rising four-note chime as the prisms link into the solar web.
  const self = this;
  [523.25, 659.25, 783.99, 1046.5].forEach(function (f, i) {
    setTimeout(function () {
      self.blip(f, 0.5, 'sine', 0.14);
    }, i * 90);
  });
};

// Continuous laser hum while the Prism Beam is channelled.
AudioEngine.prototype.beamStart = function () {
  if (!this.ctx || this.muted || this.beamOn) return;
  const ctx = this.ctx;
  this.beamOsc = ctx.createOscillator();
  this.beamOsc.type = 'sawtooth';
  this.beamOsc.frequency.value = 96;
  this.beamGain = ctx.createGain();
  this.beamGain.gain.value = 0.0;
  this.beamGain.gain.linearRampToValueAtTime(0.07, ctx.currentTime + 0.1);
  const filt = ctx.createBiquadFilter();
  filt.type = 'lowpass';
  filt.frequency.value = 900;
  this.beamOsc.connect(filt);
  filt.connect(this.beamGain);
  this.beamGain.connect(this.master);
  this.beamOsc.start();
  this.beamOn = true;
};

AudioEngine.prototype.beamStop = function () {
  if (!this.beamOn || !this.beamOsc) return;
  const osc = this.beamOsc;
  const g = this.beamGain;
  g.gain.linearRampToValueAtTime(0.0, this.ctx.currentTime + 0.08);
  setTimeout(function () {
    try {
      osc.stop();
    } catch (e) {
      /* already stopped */
    }
  }, 120);
  this.beamOsc = null;
  this.beamGain = null;
  this.beamOn = false;
};


// ---- prism-optics.js ----

// prism-optics.js — tri-chromatic refraction: the heart of the game.
// A beam fired from the Aether Loom travels until it hits a Refraction
// Prism; the prism splits it into angled sub-beams and each bounce shifts
// the chromatic phase (Cyan slows, Amber ignites, Magenta arcs lightning).
// Sub-beams can chain to a nearby prism, so three well-placed prisms turn
// one beam into a web of light. Pure geometry — no state of its own: the
// engine owns the prisms array and asks for the beam path each frame.

// Place a prism at (x, y). At most PRISM.max are active; placing one more
// repositions the oldest, so the player is always rearranging, never hoarding.
function placePrism(prisms, x, y, now) {
  const p = { x: clamp(x, 30, W - 30), y: clamp(y, 30, H - 30), angle: 0, placedAt: now, flash: 1 };
  if (prisms.length < PRISM.max) {
    prisms.push(p);
  } else {
    let oldest = 0;
    for (let i = 1; i < prisms.length; i++) {
      if (prisms[i].placedAt < prisms[oldest].placedAt) oldest = i;
    }
    prisms[oldest] = p;
  }
  return p;
}

// Trace one beam from (ox, oy) along `angle` and return its segments.
// A segment ends at a prism hit (then it splits), at an arena wall, or at
// beam range. Depth caps the recursion so a prism triangle cannot loop
// forever; `visited` stops the same prism being hit twice by one beam.
function traceBeam(prisms, ox, oy, angle, depth, visited, out) {
  const dx = Math.cos(angle);
  const dy = Math.sin(angle);
  let bestT = PLAYER.beamRange;
  let bestPrism = -1;
  for (let i = 0; i < prisms.length; i++) {
    if (visited.indexOf(i) !== -1) continue;
    const t = rayCircle(ox, oy, dx, dy, prisms[i].x, prisms[i].y, PRISM.r + 4);
    if (t >= 0 && t < bestT) {
      bestT = t;
      bestPrism = i;
    }
  }
  // Clip the segment to the arena rectangle so beams stop at the glass.
  const wallT = wallDistance(ox, oy, dx, dy);
  if (wallT >= 0 && wallT < bestT) {
    bestT = wallT;
    bestPrism = -1;
  }
  const x2 = ox + dx * bestT;
  const y2 = oy + dy * bestT;
  out.push({ x1: ox, y1: oy, x2: x2, y2: y2, phase: depth % 3, depth: depth });
  if (bestPrism === -1 || depth >= PRISM.maxDepth) return out;
  prisms[bestPrism].flash = 1;
  const nextVisited = visited.concat([bestPrism]);
  // Split: two sub-beams angled either side of the incoming beam.
  traceBeam(prisms, prisms[bestPrism].x, prisms[bestPrism].y, angle + PRISM.splitAngle, depth + 1, nextVisited, out);
  traceBeam(prisms, prisms[bestPrism].x, prisms[bestPrism].y, angle - PRISM.splitAngle, depth + 1, nextVisited, out);
  // Chain: a prism close enough to this one catches a straight relay beam.
  for (let i = 0; i < prisms.length; i++) {
    if (i === bestPrism || visited.indexOf(i) !== -1) continue;
    const d = dist(prisms[bestPrism].x, prisms[bestPrism].y, prisms[i].x, prisms[i].y);
    if (d < PRISM.chainRange) {
      const a = Math.atan2(prisms[i].y - prisms[bestPrism].y, prisms[i].x - prisms[bestPrism].x);
      traceBeam(prisms, prisms[bestPrism].x, prisms[bestPrism].y, a, depth + 1, nextVisited, out);
      break;
    }
  }
  return out;
}

// Distance along the ray to the arena's glass walls (40px margin), or -1.
function wallDistance(ox, oy, dx, dy) {
  let best = -1;
  const m = 40;
  if (dx > 0.0001) best = (W - m - ox) / dx;
  else if (dx < -0.0001) best = (m - ox) / dx;
  if (dy > 0.0001) {
    const t = (H - m - oy) / dy;
    if (t >= 0 && (best < 0 || t < best)) best = t;
  } else if (dy < -0.0001) {
    const t = (m - oy) / dy;
    if (t >= 0 && (best < 0 || t < best)) best = t;
  }
  return best;
}

// Apply one beam segment's damage to every enemy it touches, and return how
// many it hit. `onHit` receives (enemy, phase, damage) so the engine can
// apply the chromatic effects and the floating numbers.
function damageBeamSegment(seg, enemies, dps, dt, onHit) {
  let hits = 0;
  for (const e of enemies) {
    if (e.hp <= 0) continue;
    if (segDist(e.x, e.y, seg.x1, seg.y1, seg.x2, seg.y2) < e.r + 7) {
      const dmg = dps * dt;
      onHit(e, seg.phase, dmg);
      hits++;
    }
  }
  return hits;
}


// ---- entities.js ----

// entities.js — everything that moves: enemies, bolts, orbs, particles and
// floating combat text. The factory builds each enemy kind from one stat
// table; behaviour lives in updateEnemy, called once per frame by the engine.

// Base stats per enemy kind. Score is the base value before the combo
// multiplier; coreDmg is what the Astrolabe loses when one reaches it.
const ENEMY_STATS = {
  mote: { hp: 18, speed: 165, r: 11, score: 50, coreDmg: 4 },
  crawler: { hp: 42, speed: 62, r: 16, score: 80, coreDmg: 8 },
  sentinel: { hp: 95, speed: 78, r: 19, score: 150, coreDmg: 10 },
  weaver: { hp: 58, speed: 88, r: 15, score: 140, coreDmg: 6 },
  juggernaut: { hp: 330, speed: 42, r: 28, score: 400, coreDmg: 16 },
};

function makeEnemy(kind, x, y) {
  const s = ENEMY_STATS[kind];
  return {
    kind: kind,
    x: x,
    y: y,
    vx: 0,
    vy: 0,
    hp: s.hp,
    maxHp: s.hp,
    r: s.r,
    speed: s.speed,
    score: s.score,
    coreDmg: s.coreDmg,
    facing: Math.atan2(CY - y, CX - x),
    slowUntil: 0,
    burnUntil: 0,
    burnDps: 0,
    flash: 0,
    t: 0,
    teleportIn: rand(2.5, 4.5),
    shotIn: rand(1.5, 3),
    wobble: rand(0, Math.PI * 2),
  };
}

// Spawn point on the arena edge, in a random direction from the core.
function edgeSpawn() {
  const a = rand(0, Math.PI * 2);
  const r = ARENA_R + rand(20, 70);
  return { x: clamp(CX + Math.cos(a) * r, 24, W - 24), y: clamp(CY + Math.sin(a) * r, 24, H - 24) };
}

// The boss: a clockwork serpent of 7 segments orbiting the outer ring, with
// 3 destructible armor nodes riding segments 1, 3 and 5.
function makeBoss() {
  const nodes = [1, 3, 5].map(function (seg) {
    return { seg: seg, hp: BOSS.nodeHp, maxHp: BOSS.nodeHp, dead: false };
  });
  return {
    kind: 'leviathan',
    x: CX,
    y: CY - BOSS.orbitR,
    vx: 0,
    vy: 0,
    hp: BOSS.hp,
    maxHp: BOSS.hp,
    r: 34,
    speed: 0,
    score: 5000,
    coreDmg: 12,
    facing: 0,
    slowUntil: 0,
    burnUntil: 0,
    burnDps: 0,
    flash: 0,
    t: 0,
    teleportIn: 0,
    shotIn: 0,
    wobble: 0,
    orbitAngle: -Math.PI / 2,
    segments: [],
    nodes: nodes,
    flareIn: 6,
    flareState: 0, // 0 idle, 1 telegraph, 2 sweeping
    flareT: 0,
    flareAngle: 0,
    spawnIn: BOSS.spawnEvery,
  };
}

// Serpent segment positions: the head leads on the orbit and each segment
// trails behind it along the same circle.
function bossSegments(boss) {
  const segs = [];
  for (let i = 0; i < BOSS.segments; i++) {
    const a = boss.orbitAngle - i * 0.16;
    segs.push({ x: CX + Math.cos(a) * BOSS.orbitR, y: CY + Math.sin(a) * BOSS.orbitR, r: 30 - i * 2 });
  }
  return segs;
}

function makeParticle(x, y, color, speed, life, shape, size) {
  const a = rand(0, Math.PI * 2);
  const s = rand(speed * 0.3, speed);
  return {
    x: x,
    y: y,
    vx: Math.cos(a) * s,
    vy: Math.sin(a) * s,
    life: life,
    maxLife: life,
    size: size || rand(2, 4),
    color: color,
    shape: shape || 0,
    rot: rand(0, Math.PI * 2),
    vr: rand(-6, 6),
  };
}

function burst(particles, x, y, color, n, speed, life, shape) {
  for (let i = 0; i < n; i++) particles.push(makeParticle(x, y, color, speed, life * rand(0.6, 1.2), shape));
}

function makeFloatText(x, y, text, color, size) {
  return { x: x, y: y, text: text, color: color, life: 0.9, size: size || 15 };
}

function makeBolt(x, y, angle) {
  return {
    x: x,
    y: y,
    vx: Math.cos(angle) * PLAYER.boltSpeed,
    vy: Math.sin(angle) * PLAYER.boltSpeed,
    life: 1.1,
  };
}

function makeOrb(x, y, tx, ty) {
  const a = Math.atan2(ty - y, tx - x);
  const sp = 110;
  return { x: x, y: y, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp, r: 9, life: 9 };
}

// Steer one enemy toward the core for dt seconds. Returns nothing; the
// engine reads the enemy's position and velocity afterwards.
function updateEnemy(e, dt, now, orbs, coreX, coreY) {
  e.t += dt;
  if (e.flash > 0) e.flash = Math.max(0, e.flash - dt * 5);
  // Amber burn ticks down here so every damage path shares one rule.
  if (e.burnUntil > now) {
    e.hp -= e.burnDps * dt;
  }
  const slow = e.slowUntil > now ? PHASES[0].slow : 1;
  const dx = coreX - e.x;
  const dy = coreY - e.y;
  const d = Math.sqrt(dx * dx + dy * dy) || 1;
  const sp = e.speed * slow;
  let mx = (dx / d) * sp;
  let my = (dy / d) * sp;

  if (e.kind === 'mote') {
    // Fast swarmers wobble as they close in.
    const w = Math.sin(e.t * 5 + e.wobble) * 40;
    mx += (-dy / d) * w * 0.4;
    my += (dx / d) * w * 0.4;
  } else if (e.kind === 'weaver') {
    // Rift Weavers blink away and lob slow void orbs at the core.
    e.teleportIn -= dt;
    if (e.teleportIn <= 0) {
      e.teleportIn = rand(3.5, 5.5);
      const p = edgeSpawn();
      e.x = p.x;
      e.y = p.y;
    }
    e.shotIn -= dt;
    if (e.shotIn <= 0) {
      e.shotIn = rand(2.5, 4);
      orbs.push(makeOrb(e.x, e.y, coreX, coreY));
    }
  }
  // Sentinels and Juggernauts move straight; their flavour is in damage.
  e.vx = mx;
  e.vy = my;
  e.x += mx * dt;
  e.y += my * dt;
  e.facing = Math.atan2(my, mx);
}


// ---- waves.js ----

// waves.js — the five Astral Cycles: what spawns, in what order, and when a
// cycle is done. Each cycle is a timed queue of spawn events; the engine
// drains the queue and the cycle ends when the queue is empty and every
// enemy (boss included) is dead.

// kind, count, gap (seconds between spawns of this group), firstDelay.
const CYCLES = [
  {
    name: 'Cycle I — First Light',
    groups: [
      { kind: 'mote', count: 8, gap: 0.9, delay: 0.5 },
      { kind: 'crawler', count: 4, gap: 1.6, delay: 4 },
      { kind: 'mote', count: 6, gap: 0.7, delay: 8 },
    ],
  },
  {
    name: 'Cycle II — Mirror Wall',
    groups: [
      { kind: 'mote', count: 8, gap: 0.8, delay: 0.5 },
      { kind: 'sentinel', count: 3, gap: 2.5, delay: 3 },
      { kind: 'crawler', count: 5, gap: 1.4, delay: 7 },
      { kind: 'sentinel', count: 2, gap: 2.5, delay: 12 },
    ],
  },
  {
    name: 'Cycle III — Rift Choir',
    groups: [
      { kind: 'weaver', count: 2, gap: 3, delay: 0.5 },
      { kind: 'mote', count: 10, gap: 0.6, delay: 3 },
      { kind: 'sentinel', count: 3, gap: 2.2, delay: 8 },
      { kind: 'weaver', count: 2, gap: 3, delay: 13 },
      { kind: 'crawler', count: 4, gap: 1.2, delay: 16 },
    ],
  },
  {
    name: 'Cycle IV — Obsidian Tide',
    groups: [
      { kind: 'juggernaut', count: 1, gap: 0, delay: 0.5 },
      { kind: 'mote', count: 12, gap: 0.55, delay: 2 },
      { kind: 'weaver', count: 2, gap: 3, delay: 6 },
      { kind: 'sentinel', count: 4, gap: 2, delay: 10 },
      { kind: 'juggernaut', count: 1, gap: 0, delay: 15 },
      { kind: 'crawler', count: 6, gap: 1.1, delay: 18 },
    ],
  },
  {
    name: 'Cycle V — The Eclipse Leviathan',
    groups: [
      { kind: 'mote', count: 6, gap: 0.8, delay: 1 },
      { kind: 'weaver', count: 2, gap: 3, delay: 6 },
    ],
  },
];

// Expand a cycle definition into a flat, time-sorted spawn queue.
function buildQueue(cycleIndex) {
  const queue = [];
  for (const g of CYCLES[cycleIndex].groups) {
    for (let i = 0; i < g.count; i++) {
      queue.push({ kind: g.kind, at: g.delay + i * g.gap });
    }
  }
  queue.sort(function (a, b) {
    return a.at - b.at;
  });
  return queue;
}

// A cycle is complete when its queue is drained and nothing hostile remains.
function cycleCleared(queue, enemies, boss) {
  if (queue.length > 0) return false;
  if (enemies.length > 0) return false;
  if (boss && boss.hp > 0) return false;
  return true;
}


// ---- renderer.js ----

// renderer.js — everything drawn: the parallax starfield, the brass
// astrolabe, the core, the loom, prisms, beams, enemies, the boss, and the
// diegetic HUD plus every menu screen. All glow uses additive blending
// ('lighter') so overlapping light feels like light.

// Starfield, generated once from the seeded RNG so screenshots are stable.
let STARS = null;
function starfield() {
  if (STARS) return STARS;
  STARS = [];
  for (let i = 0; i < 170; i++) {
    STARS.push({
      x: rand(0, W),
      y: rand(0, H),
      r: rand(0.5, 1.8),
      layer: pick([0.2, 0.5, 1]),
      tw: rand(0, Math.PI * 2),
    });
  }
  return STARS;
}

function drawBackground(ctx, t) {
  const g = ctx.createRadialGradient(CX, CY, 80, CX, CY, 720);
  g.addColorStop(0, '#101736');
  g.addColorStop(0.55, COL.bg2);
  g.addColorStop(1, COL.bg);
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);
  for (const s of starfield()) {
    const a = 0.25 + 0.55 * Math.abs(Math.sin(t * 0.6 * s.layer + s.tw));
    ctx.globalAlpha = a;
    ctx.fillStyle = '#cdd7ff';
    ctx.beginPath();
    ctx.arc(s.x + Math.sin(t * 0.02 * s.layer) * 6, s.y, s.r, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.globalAlpha = 1;
  // Slowly rotating brass astrolabe rings around the core.
  ctx.save();
  ctx.translate(CX, CY);
  ctx.rotate(t * 0.02);
  ctx.strokeStyle = COL.brassDim;
  ctx.lineWidth = 2;
  for (const r of [120, 190, 265]) {
    ctx.beginPath();
    ctx.arc(0, 0, r, 0, Math.PI * 2);
    ctx.stroke();
  }
  ctx.rotate(-t * 0.05);
  for (let i = 0; i < 24; i++) {
    const a = (i / 24) * Math.PI * 2;
    ctx.beginPath();
    ctx.moveTo(Math.cos(a) * 258, Math.sin(a) * 258);
    ctx.lineTo(Math.cos(a) * 272, Math.sin(a) * 272);
    ctx.stroke();
  }
  ctx.restore();
}

function drawCore(ctx, G, t) {
  const hpFrac = G.coreHp / CORE.hpMax;
  const pulse = 1 + Math.sin(t * 2.2) * 0.04;
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  const glow = ctx.createRadialGradient(CX, CY, 10, CX, CY, 130);
  glow.addColorStop(0, 'rgba(255,233,168,0.55)');
  glow.addColorStop(0.4, 'rgba(200,157,84,0.18)');
  glow.addColorStop(1, 'rgba(200,157,84,0)');
  ctx.fillStyle = glow;
  ctx.beginPath();
  ctx.arc(CX, CY, 130, 0, Math.PI * 2);
  ctx.fill();
  ctx.globalCompositeOperation = 'source-over';
  // Brass ring + glass orb; the orb drains from gold to red as it takes hits.
  ctx.strokeStyle = COL.brass;
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(CX, CY, CORE_R * pulse, 0, Math.PI * 2);
  ctx.stroke();
  const orb = ctx.createRadialGradient(CX - 12, CY - 14, 4, CX, CY, CORE_R);
  const hot = hpFrac > 0.5 ? '255,233,168' : '255,110,110';
  orb.addColorStop(0, 'rgba(' + hot + ',0.95)');
  orb.addColorStop(1, 'rgba(120,80,30,0.9)');
  ctx.fillStyle = orb;
  ctx.beginPath();
  ctx.arc(CX, CY, CORE_R - 4, 0, Math.PI * 2);
  ctx.fill();
  // Tick marks show integrity at a glance.
  ctx.strokeStyle = 'rgba(7,9,19,0.7)';
  ctx.lineWidth = 2;
  for (let i = 0; i < 10; i++) {
    if (i / 10 >= hpFrac) continue;
    const a = (i / 10) * Math.PI * 2 - Math.PI / 2;
    ctx.beginPath();
    ctx.moveTo(CX + Math.cos(a) * (CORE_R - 12), CY + Math.sin(a) * (CORE_R - 12));
    ctx.lineTo(CX + Math.cos(a) * (CORE_R - 5), CY + Math.sin(a) * (CORE_R - 5));
    ctx.stroke();
  }
  ctx.restore();
}

function drawPlayer(ctx, G, t) {
  const p = G.player;
  if (p.dead) return;
  ctx.save();
  ctx.translate(p.x, p.y);
  // Afterimage trail while dashing.
  if (p.dashT > 0) {
    ctx.globalAlpha = 0.35;
    ctx.fillStyle = COL.cyan;
    ctx.beginPath();
    ctx.arc(-p.vx * 0.03, -p.vy * 0.03, p.r * 0.9, 0, Math.PI * 2);
    ctx.fill();
    ctx.globalAlpha = 1;
  }
  ctx.rotate(p.aim);
  ctx.globalCompositeOperation = 'lighter';
  ctx.fillStyle = 'rgba(53,224,255,0.25)';
  ctx.beginPath();
  ctx.arc(0, 0, 26 + Math.sin(t * 4) * 2, 0, Math.PI * 2);
  ctx.fill();
  ctx.globalCompositeOperation = 'source-over';
  // The Aether Loom: a brass dart with a cyan heart.
  ctx.fillStyle = COL.brass;
  ctx.beginPath();
  ctx.moveTo(20, 0);
  ctx.lineTo(-12, -11);
  ctx.lineTo(-6, 0);
  ctx.lineTo(-12, 11);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = COL.cyan;
  ctx.beginPath();
  ctx.arc(2, 0, 5, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
  // Laser sightline preview: a short faint dash ahead of the ship, showing
  // the aim direction without drawing a line across the whole arena.
  ctx.save();
  ctx.strokeStyle = 'rgba(53,224,255,0.4)';
  ctx.setLineDash([4, 10]);
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(p.x + Math.cos(p.aim) * 26, p.y + Math.sin(p.aim) * 26);
  ctx.lineTo(p.x + Math.cos(p.aim) * 150, p.y + Math.sin(p.aim) * 150);
  ctx.stroke();
  ctx.setLineDash([]);
  ctx.restore();
}

function drawPrism(ctx, p, t) {
  ctx.save();
  ctx.translate(p.x, p.y);
  ctx.globalCompositeOperation = 'lighter';
  ctx.fillStyle = 'rgba(255,255,255,' + (0.10 + p.flash * 0.25) + ')';
  ctx.beginPath();
  ctx.arc(0, 0, 26 + p.flash * 8, 0, Math.PI * 2);
  ctx.fill();
  ctx.globalCompositeOperation = 'source-over';
  ctx.rotate(p.angle + t * 0.3);
  // Triangular glass prism with a tri-chromatic facet.
  const grad = ctx.createLinearGradient(-14, -10, 14, 12);
  grad.addColorStop(0, COL.cyan);
  grad.addColorStop(0.5, '#e8ecff');
  grad.addColorStop(1, COL.magenta);
  ctx.fillStyle = grad;
  ctx.globalAlpha = 0.9;
  ctx.beginPath();
  ctx.moveTo(0, -17);
  ctx.lineTo(15, 11);
  ctx.lineTo(-15, 11);
  ctx.closePath();
  ctx.fill();
  ctx.globalAlpha = 1;
  ctx.strokeStyle = '#ffffff';
  ctx.lineWidth = 1.5;
  ctx.stroke();
  ctx.restore();
}

function drawBeamSegments(ctx, segs, t) {
  if (!segs.length) return;
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  ctx.lineCap = 'round';
  for (const s of segs) {
    const col = PHASES[s.phase].color;
    const wob = Math.sin(t * 30 + s.depth * 2) * 1.2;
    ctx.strokeStyle = col;
    ctx.globalAlpha = 0.9;
    ctx.lineWidth = 3.5;
    ctx.beginPath();
    ctx.moveTo(s.x1, s.y1);
    ctx.lineTo(s.x2 + wob, s.y2);
    ctx.stroke();
    ctx.globalAlpha = 0.28;
    ctx.lineWidth = 10;
    ctx.beginPath();
    ctx.moveTo(s.x1, s.y1);
    ctx.lineTo(s.x2, s.y2);
    ctx.stroke();
    // Bright node where the beam bends.
    ctx.globalAlpha = 0.9;
    ctx.fillStyle = '#ffffff';
    ctx.beginPath();
    ctx.arc(s.x1, s.y1, 3, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.restore();
}

function drawConvergenceWeb(ctx, G, t) {
  const ps = G.prisms;
  if (ps.length < 2) return;
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  ctx.strokeStyle = 'rgba(255,255,255,0.85)';
  ctx.lineWidth = 2.5;
  ctx.beginPath();
  ctx.moveTo(ps[0].x, ps[0].y);
  for (let i = 1; i < ps.length; i++) ctx.lineTo(ps[i].x, ps[i].y);
  ctx.closePath();
  ctx.stroke();
  ctx.fillStyle = 'rgba(255,79,216,0.10)';
  ctx.fill();
  ctx.restore();
}

function drawEnemy(ctx, e, t) {
  ctx.save();
  ctx.translate(e.x, e.y);
  const flash = e.flash > 0;
  const body = flash ? '#ffffff' : enemyColor(e.kind);
  ctx.globalCompositeOperation = 'lighter';
  ctx.fillStyle = glowColor(e.kind);
  ctx.beginPath();
  ctx.arc(0, 0, e.r + 8, 0, Math.PI * 2);
  ctx.fill();
  ctx.globalCompositeOperation = 'source-over';
  ctx.rotate(e.facing);
  ctx.fillStyle = body;
  ctx.strokeStyle = '#0b0f24';
  ctx.lineWidth = 2;
  if (e.kind === 'mote') {
    ctx.beginPath();
    for (let i = 0; i < 6; i++) {
      const a = (i / 6) * Math.PI * 2 + t * 2;
      const rr = i % 2 === 0 ? e.r : e.r * 0.55;
      const px = Math.cos(a) * rr;
      const py = Math.sin(a) * rr;
      if (i === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.closePath();
    ctx.fill();
  } else if (e.kind === 'crawler') {
    hexPath(ctx, e.r);
    ctx.fill();
    ctx.stroke();
  } else if (e.kind === 'sentinel') {
    ctx.fillRect(-e.r, -e.r, e.r * 2, e.r * 2);
    ctx.strokeRect(-e.r, -e.r, e.r * 2, e.r * 2);
    // Frontal shield arc — the side you must not shoot.
    ctx.strokeStyle = 'rgba(53,224,255,0.9)';
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.arc(0, 0, e.r + 5, -0.9, 0.9);
    ctx.stroke();
  } else if (e.kind === 'weaver') {
    ctx.rotate(Math.PI / 4);
    ctx.fillRect(-e.r * 0.8, -e.r * 0.8, e.r * 1.6, e.r * 1.6);
    ctx.strokeStyle = COL.magenta;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(0, 0, e.r + 6, t * 2, t * 2 + Math.PI * 1.4);
    ctx.stroke();
  } else if (e.kind === 'juggernaut') {
    hexPath(ctx, e.r);
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = '#2a2f4a';
    hexPath(ctx, e.r * 0.55);
    ctx.fill();
  }
  ctx.restore();
  // HP bar for anything tougher than a mote.
  if (e.maxHp > 20 && e.hp < e.maxHp) {
    ctx.fillStyle = 'rgba(0,0,0,0.55)';
    ctx.fillRect(e.x - 18, e.y - e.r - 12, 36, 5);
    ctx.fillStyle = COL.danger;
    ctx.fillRect(e.x - 18, e.y - e.r - 12, 36 * clamp(e.hp / e.maxHp, 0, 1), 5);
  }
  // Burn / slow status rings.
  if (e.burnUntil > 0) {
    ctx.strokeStyle = COL.amber;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(e.x, e.y, e.r + 3, 0, Math.PI * 2);
    ctx.stroke();
  }
}

function hexPath(ctx, r) {
  ctx.beginPath();
  for (let i = 0; i < 6; i++) {
    const a = (i / 6) * Math.PI * 2;
    const px = Math.cos(a) * r;
    const py = Math.sin(a) * r;
    if (i === 0) ctx.moveTo(px, py);
    else ctx.lineTo(px, py);
  }
  ctx.closePath();
}

function enemyColor(kind) {
  if (kind === 'mote') return '#8a5cff';
  if (kind === 'crawler') return '#5c6b8a';
  if (kind === 'sentinel') return '#3fd2c0';
  if (kind === 'weaver') return '#b04fd8';
  return '#3a3f5c'; // juggernaut
}

function glowColor(kind) {
  if (kind === 'mote') return 'rgba(138,92,255,0.22)';
  if (kind === 'crawler') return 'rgba(92,107,138,0.18)';
  if (kind === 'sentinel') return 'rgba(63,210,192,0.20)';
  if (kind === 'weaver') return 'rgba(176,79,216,0.25)';
  return 'rgba(120,90,160,0.25)';
}

function drawBoss(ctx, boss, t) {
  const segs = bossSegments(boss);
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  for (const s of segs) {
    ctx.fillStyle = 'rgba(255,84,112,0.16)';
    ctx.beginPath();
    ctx.arc(s.x, s.y, s.r + 10, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.globalCompositeOperation = 'source-over';
  // Flare telegraph: a warning sector before the sweep.
  if (boss.flareState === 1) {
    ctx.fillStyle = 'rgba(255,84,112,0.18)';
    ctx.beginPath();
    ctx.moveTo(CX, CY);
    ctx.arc(CX, CY, 560, boss.flareAngle - 0.5, boss.flareAngle + 0.5);
    ctx.closePath();
    ctx.fill();
  }
  for (let i = segs.length - 1; i >= 0; i--) {
    const s = segs[i];
    ctx.fillStyle = i === 0 ? '#ff5470' : '#5c2440';
    ctx.strokeStyle = COL.brass;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(s.x, s.y, s.r, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
    // Clockwork eye on the head.
    if (i === 0) {
      ctx.fillStyle = '#ffe9a8';
      ctx.beginPath();
      ctx.arc(s.x, s.y, 7, 0, Math.PI * 2);
      ctx.fill();
    }
  }
  // Armor nodes: glowing weak points riding the serpent.
  for (const n of boss.nodes) {
    if (n.dead) continue;
    const s = segs[n.seg];
    ctx.fillStyle = '#ffd76a';
    ctx.strokeStyle = '#fff';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(s.x, s.y, 12, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = '#070913';
    ctx.font = 'bold 12px system-ui, sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('◆', s.x, s.y + 1);
  }
  ctx.restore();
}

function drawParticles(ctx, particles) {
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  for (const p of particles) {
    const a = clamp(p.life / p.maxLife, 0, 1);
    ctx.globalAlpha = a;
    ctx.fillStyle = p.color;
    if (p.shape === 1) {
      ctx.save();
      ctx.translate(p.x, p.y);
      ctx.rotate(p.rot);
      ctx.beginPath();
      ctx.moveTo(0, -p.size);
      ctx.lineTo(p.size, p.size);
      ctx.lineTo(-p.size, p.size);
      ctx.closePath();
      ctx.fill();
      ctx.restore();
    } else if (p.shape === 2) {
      ctx.strokeStyle = p.color;
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.size * (2 - a), 0, Math.PI * 2);
      ctx.stroke();
    } else {
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.size * a + 0.5, 0, Math.PI * 2);
      ctx.fill();
    }
  }
  ctx.restore();
}

function drawFloatTexts(ctx, texts) {
  ctx.save();
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  for (const f of texts) {
    ctx.globalAlpha = clamp(f.life / 0.9, 0, 1);
    ctx.font = 'bold ' + f.size + 'px system-ui, sans-serif';
    ctx.fillStyle = f.color;
    ctx.fillText(f.text, f.x, f.y);
  }
  ctx.restore();
}

function drawOrbs(ctx, orbs) {
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  for (const o of orbs) {
    ctx.fillStyle = 'rgba(176,79,216,0.5)';
    ctx.beginPath();
    ctx.arc(o.x, o.y, o.r + 6, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = '#d9a0ff';
    ctx.beginPath();
    ctx.arc(o.x, o.y, o.r, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.restore();
}

function drawBolts(ctx, bolts) {
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  ctx.strokeStyle = '#ffe9a8';
  ctx.lineWidth = 3;
  ctx.lineCap = 'round';
  for (const b of bolts) {
    ctx.beginPath();
    ctx.moveTo(b.x - b.vx * 0.02, b.y - b.vy * 0.02);
    ctx.lineTo(b.x, b.y);
    ctx.stroke();
  }
  ctx.restore();
}

// ---- HUD ----

function bar(ctx, x, y, w, h, frac, fill, label, text) {
  ctx.fillStyle = 'rgba(0,0,0,0.55)';
  ctx.fillRect(x, y, w, h);
  ctx.fillStyle = fill;
  ctx.fillRect(x, y, w * clamp(frac, 0, 1), h);
  ctx.strokeStyle = 'rgba(232,236,255,0.35)';
  ctx.lineWidth = 1;
  ctx.strokeRect(x, y, w, h);
  ctx.fillStyle = COL.ink;
  ctx.font = 'bold 12px system-ui, sans-serif';
  ctx.textAlign = 'left';
  ctx.textBaseline = 'middle';
  ctx.fillText(label, x, y - 9);
  ctx.textAlign = 'right';
  ctx.fillText(text, x + w, y - 9);
}

function drawHUD(ctx, G) {
  ctx.save();
  // Top-left: Core Integrity + Aether Energy.
  const coreFrac = G.coreHp / CORE.hpMax;
  bar(ctx, 24, 40, 220, 12, coreFrac, coreFrac > 0.5 ? COL.good : COL.danger, 'CORE INTEGRITY', Math.ceil(G.coreHp) + '%');
  const enFrac = G.energy / PLAYER.energyMax;
  bar(ctx, 24, 72, 220, 12, enFrac, COL.cyan, 'AETHER ENERGY', Math.floor(G.energy) + '');
  // Top-centre: cycle progress, and the boss bar on Cycle V.
  ctx.textAlign = 'center';
  ctx.fillStyle = COL.ink;
  ctx.font = 'bold 16px system-ui, sans-serif';
  ctx.fillText(CYCLES[G.cycle].name.toUpperCase(), CX, 30);
  const total = G.cycleTotal || 1;
  const done = total - G.queue.length - G.enemies.length - (G.boss && G.boss.hp > 0 ? 1 : 0);
  ctx.fillStyle = 'rgba(0,0,0,0.55)';
  ctx.fillRect(CX - 140, 40, 280, 8);
  ctx.fillStyle = COL.brass;
  ctx.fillRect(CX - 140, 40, 280 * clamp(done / total, 0, 1), 8);
  if (G.boss && G.boss.hp > 0) {
    ctx.fillStyle = COL.danger;
    ctx.font = 'bold 13px system-ui, sans-serif';
    ctx.fillText('THE ECLIPSE LEVIATHAN', CX, 66);
    ctx.fillStyle = 'rgba(0,0,0,0.55)';
    ctx.fillRect(CX - 160, 74, 320, 9);
    ctx.fillStyle = COL.danger;
    ctx.fillRect(CX - 160, 74, 320 * clamp(G.boss.hp / G.boss.maxHp, 0, 1), 9);
  }
  // Top-right: score, combo, convergence.
  ctx.textAlign = 'right';
  ctx.fillStyle = COL.ink;
  ctx.font = 'bold 22px system-ui, sans-serif';
  ctx.fillText(G.score.toLocaleString('en-US'), W - 24, 32);
  ctx.font = 'bold 13px system-ui, sans-serif';
  ctx.fillStyle = G.combo > 1 ? COL.amber : COL.dim;
  ctx.fillText('COMBO x' + G.multiplier + '  (' + G.combo + ')', W - 24, 54);
  const resFrac = G.resonance / 100;
  bar(ctx, W - 244, 86, 220, 12, resFrac, COL.magenta, 'HARMONIC RESONANCE [Q]', resFrac >= 1 ? 'READY' : Math.floor(G.resonance) + '%');
  // Bottom hints: dash cooldown + controls reminder.
  ctx.textAlign = 'left';
  ctx.fillStyle = COL.dim;
  ctx.font = '12px system-ui, sans-serif';
  const dashReady = G.dashCd <= 0;
  ctx.fillText(
    (dashReady ? '◆ DASH READY [Space]' : '◇ Dash ' + G.dashCd.toFixed(1) + 's') +
      '   ·   Right-click / E: prism   ·   M: mute   ·   P: pause',
    24,
    H - 16,
  );
  ctx.restore();
}

function drawBanner(ctx, G) {
  if (!G.banner) return;
  ctx.save();
  ctx.globalAlpha = clamp(G.bannerT, 0, 1);
  ctx.textAlign = 'center';
  ctx.fillStyle = COL.brass;
  ctx.font = 'bold 34px Georgia, serif';
  ctx.fillText(G.banner, CX, 150);
  ctx.restore();
}

// ---- Screens ----

function screenShell(ctx, title, sub) {
  ctx.fillStyle = 'rgba(7,9,19,0.72)';
  ctx.fillRect(0, 0, W, H);
  ctx.textAlign = 'center';
  ctx.fillStyle = COL.brass;
  ctx.font = 'bold 54px Georgia, serif';
  ctx.fillText(title, CX, 210);
  ctx.fillStyle = COL.ink;
  ctx.font = '20px Georgia, serif';
  ctx.fillText(sub, CX, 252);
}

function drawTitle(ctx, G) {
  drawBackground(ctx, G.time);
  drawCore(ctx, G, G.time);
  screenShell(ctx, 'LUMENWEAVE', 'P R I S M   W A R D E N');
  ctx.save();
  ctx.textAlign = 'center';
  ctx.fillStyle = COL.dim;
  ctx.font = '17px system-ui, sans-serif';
  ctx.fillText('Defend the Chrono-Astrolabe Core across five Astral Cycles.', CX, 300);
  ctx.fillText('Bend photonic beams through Refraction Prisms — split the light, break the dark.', CX, 326);
  ctx.fillStyle = COL.ink;
  ctx.font = '15px system-ui, sans-serif';
  const lines = [
    'WASD / Arrows — move      Mouse — aim      Click — Solar Bolts      Hold — Prism Beam',
    'Right-click / E — place Prism (max 3)      Space — Phase-Dash      Q — Solar Convergence at 100%',
    'Cyan slows · Amber ignites · Magenta arcs lightning',
  ];
  lines.forEach(function (l, i) {
    ctx.fillText(l, CX, 380 + i * 26);
  });
  ctx.fillStyle = G.time % 1 < 0.6 ? COL.amber : COL.dim;
  ctx.font = 'bold 22px system-ui, sans-serif';
  ctx.fillText('— CLICK OR PRESS ENTER TO BEGIN —', CX, 500);
  ctx.fillStyle = COL.dim;
  ctx.font = '13px system-ui, sans-serif';
  ctx.fillText('An original game · sound is procedural · M mutes · P pauses', CX, 640);
  ctx.restore();
}

function drawPause(ctx) {
  screenShell(ctx, 'PAUSED', 'The light holds its breath.');
  ctx.save();
  ctx.textAlign = 'center';
  ctx.fillStyle = COL.dim;
  ctx.font = '16px system-ui, sans-serif';
  ctx.fillText('P / Esc — resume      M — mute      R — restart run', CX, 310);
  ctx.restore();
}

function statLines(ctx, G, y0) {
  const rows = [
    ['Final Score', G.score.toLocaleString('en-US')],
    ['Max Combo', 'x' + G.maxMultiplier + '  (' + G.maxCombo + ' chained kills)'],
    ['Ricochet Kills', String(G.ricochetKills)],
    ['Accuracy', G.shotsFired > 0 ? Math.round((100 * G.shotsHit) / G.shotsFired) + '%' : '—'],
    ['Cycles Cleared', String(G.cyclesCleared) + ' / 5'],
    ['Prisms Placed', String(G.prismsPlaced)],
  ];
  ctx.save();
  ctx.font = '17px system-ui, sans-serif';
  rows.forEach(function (r, i) {
    const y = y0 + i * 30;
    ctx.textAlign = 'right';
    ctx.fillStyle = COL.dim;
    ctx.fillText(r[0], CX - 12, y);
    ctx.textAlign = 'left';
    ctx.fillStyle = COL.ink;
    ctx.fillText(r[1], CX + 12, y);
  });
  ctx.restore();
}

function drawVictory(ctx, G) {
  screenShell(ctx, 'ASTRAL ASCENSION', 'The Eclipse Leviathan is unmade. The Core burns bright again.');
  statLines(ctx, G, 320);
  ctx.save();
  ctx.textAlign = 'center';
  ctx.fillStyle = G.time % 1 < 0.6 ? COL.amber : COL.dim;
  ctx.font = 'bold 20px system-ui, sans-serif';
  ctx.fillText('— PLAY AGAIN [Enter] —', CX, 540);
  ctx.restore();
}

function drawGameOver(ctx, G) {
  screenShell(ctx, 'ASTROLABE SHATTERED', 'The Core has gone dark. The weave unravels… for now.');
  statLines(ctx, G, 320);
  ctx.save();
  ctx.textAlign = 'center';
  ctx.fillStyle = G.time % 1 < 0.6 ? COL.amber : COL.dim;
  ctx.font = 'bold 20px system-ui, sans-serif';
  ctx.fillText('— RESTART [Enter] —', CX, 540);
  ctx.restore();
}

// Master draw: world first, then HUD, then the screen overlay for the state.
function drawGame(ctx, G) {
  ctx.save();
  if (G.shake > 0.2) {
    ctx.translate(rand(-G.shake, G.shake), rand(-G.shake, G.shake));
  }
  drawBackground(ctx, G.time);
  drawCore(ctx, G, G.time);
  for (const p of G.prisms) drawPrism(ctx, p, G.time);
  if (G.state === 'play' || G.state === 'over' || G.state === 'victory') {
    drawBeamSegments(ctx, G.beamSegs, G.time);
    if (G.convergenceT > 0) drawConvergenceWeb(ctx, G, G.time);
    drawBolts(ctx, G.bolts);
    drawOrbs(ctx, G.orbs);
    for (const e of G.enemies) drawEnemy(ctx, e, G.time);
    if (G.boss && G.boss.hp > 0) drawBoss(ctx, G.boss, G.time);
    drawPlayer(ctx, G, G.time);
    drawParticles(ctx, G.particles);
    drawFloatTexts(ctx, G.texts);
  }
  ctx.restore();
  if (G.state === 'play' || G.state === 'paused') drawHUD(ctx, G);
  drawBanner(ctx, G);
  if (G.state === 'title') drawTitle(ctx, G);
  else if (G.state === 'paused') drawPause(ctx);
  else if (G.state === 'victory') drawVictory(ctx, G);
  else if (G.state === 'over') drawGameOver(ctx, G);
}


// ---- engine.js ----

// engine.js — the game itself: state, input, the main loop, combat,
// cycles, the boss fight, scoring, and the deterministic screenshot mode
// (?shot=title|play|intense|gameover&seed=1) used for the entry's renders.

// ---- State ----

function freshState() {
  return {
    state: 'title', // title | play | paused | victory | over
    time: 0,
    frozen: false, // screenshot mode: render one frozen frame
    coreHp: CORE.hpMax,
    energy: PLAYER.energyMax,
    score: 0,
    combo: 0,
    multiplier: 1,
    maxCombo: 0,
    maxMultiplier: 1,
    resonance: 0,
    cycle: 0,
    queue: [],
    cycleTotal: 1,
    enemies: [],
    boss: null,
    prisms: [],
    bolts: [],
    orbs: [],
    particles: [],
    texts: [],
    beamSegs: [],
    beaming: false,
    beamHoldT: 0,
    convergenceT: 0,
    dashCd: 0,
    dashT: 0,
    shake: 0,
    hitStop: 0,
    banner: '',
    bannerT: 0,
    intermissionT: 0,
    chimeCd: 0,
    shotsFired: 0,
    shotsHit: 0,
    ricochetKills: 0,
    cyclesCleared: 0,
    prismsPlaced: 0,
    player: {
      x: CX,
      y: CY + 140,
      vx: 0,
      vy: 0,
      aim: -Math.PI / 2,
      hull: PLAYER.hullMax,
      dead: false,
      respawnT: 0,
      invulnT: 0,
      lastHurt: -9,
    },
    mouse: { x: CX, y: CY - 120, left: false, pressT: 0 },
    keys: {},
    audio: new AudioEngine(),
  };
}

let G = freshState();
let canvas = null;
let ctx = null;

// ---- Run control ----

function startRun() {
  const audio = G.audio;
  G = freshState();
  G.audio = audio;
  G.state = 'play';
  startCycle(0);
}

function startCycle(n) {
  G.cycle = n;
  G.queue = buildQueue(n);
  G.cycleTotal = G.queue.length + (n === 4 ? 1 : 0);
  G.banner = CYCLES[n].name;
  G.bannerT = 2.6;
  if (n === 4) {
    G.boss = makeBoss();
    G.audio.horn();
  }
}

function nextCycle() {
  G.cyclesCleared = G.cycle + 1;
  if (G.cycle >= 4) return;
  startCycle(G.cycle + 1);
}

function endRun(victory) {
  G.state = victory ? 'victory' : 'over';
  G.beaming = false;
  G.beamSegs = []; // no stray beam across the end screen
  G.audio.beamStop();
  if (victory) {
    G.audio.shatter();
    burst(G.particles, CX, CY, COL.amber, 60, 320, 1.4, 1);
  }
}

// ---- Combat helpers ----

function addScore(base, x, y, label) {
  const gained = base * G.multiplier;
  G.score += gained;
  G.texts.push(makeFloatText(x, y - 10, '+' + gained, '#ffe9a8', 16));
  if (label) G.texts.push(makeFloatText(x, y - 30, label, COL.dim, 12));
}

function registerKill(e, ricochet) {
  G.combo += 1;
  G.maxCombo = Math.max(G.maxCombo, G.combo);
  G.multiplier = Math.min(COMBO_MAX, 1 + Math.floor(G.combo / COMBO_STEP));
  G.maxMultiplier = Math.max(G.maxMultiplier, G.multiplier);
  G.resonance = Math.min(100, G.resonance + RESONANCE_PER_KILL);
  if (ricochet) G.ricochetKills += 1;
  addScore(e.score, e.x, e.y, G.multiplier > 1 ? 'x' + G.multiplier : '');
  burst(G.particles, e.x, e.y, enemyColor(e.kind), 14, 200, 0.7, 1);
  G.audio.chime(G.combo);
}

function damageEnemy(e, dmg, fromAngle, ricochet) {
  if (e.hp <= 0) return;
  // Mirror Sentinels: a frontal hit is mostly deflected — flank them,
  // ideally with a prism ricochet coming from another direction.
  if (e.kind === 'sentinel' && fromAngle !== null) {
    if (Math.abs(angleDiff(e.facing, fromAngle)) < 1.0) {
      dmg *= 0.2;
      G.texts.push(makeFloatText(e.x, e.y - e.r - 6, 'SHIELDED', COL.cyan, 12));
    }
  }
  e.hp -= dmg;
  e.flash = 1;
  if (e.hp <= 0) registerKill(e, ricochet);
}

function applyChromatic(e, phase, now) {
  const ph = PHASES[phase];
  if (ph.slow < 1) e.slowUntil = now + 2;
  if (ph.burn > 0) {
    e.burnUntil = now + 3;
    e.burnDps = ph.burn;
  }
  if (ph.arc > 0) {
    // Magenta arcs lightning to up to 2 nearby enemies.
    let chained = 0;
    for (const o of G.enemies) {
      if (o === e || o.hp <= 0 || chained >= ph.arc) continue;
      if (dist(e.x, e.y, o.x, o.y) < 150) {
        o.hp -= 12;
        o.flash = 1;
        G.texts.push(makeFloatText(o.x, o.y - o.r - 4, '12', COL.magenta, 13));
        if (o.hp <= 0) registerKill(o, true);
        chained++;
      }
    }
  }
}

function hurtCore(dmg, x, y) {
  G.coreHp -= dmg;
  G.combo = 0;
  G.multiplier = 1;
  G.shake = Math.max(G.shake, 9);
  G.audio.coreHit();
  burst(G.particles, x, y, COL.danger, 16, 240, 0.8, 1);
  G.texts.push(makeFloatText(x, y - 20, '-' + dmg + ' CORE', COL.danger, 15));
  if (G.coreHp <= 0) {
    G.coreHp = 0;
    endRun(false);
  }
}

function hurtPlayer(dmg) {
  const p = G.player;
  if (p.invulnT > 0 || p.dashT > 0 || p.dead) return;
  p.hull -= dmg;
  p.invulnT = 0.7;
  p.lastHurt = G.time;
  G.shake = Math.max(G.shake, 6);
  if (p.hull <= 0) {
    p.hull = 0;
    p.dead = true;
    p.respawnT = 2;
    G.combo = 0;
    G.multiplier = 1;
    burst(G.particles, p.x, p.y, COL.cyan, 30, 300, 1, 1);
    G.audio.shatter();
  }
}

// ---- Player actions ----

function fireBolt() {
  const p = G.player;
  if (p.dead || G.energy < PLAYER.boltEnergy) return;
  G.energy -= PLAYER.boltEnergy;
  G.bolts.push(makeBolt(p.x + Math.cos(p.aim) * 20, p.y + Math.sin(p.aim) * 20, p.aim));
  G.shotsFired += 1;
  G.audio.shoot();
}

function doDash() {
  const p = G.player;
  if (G.dashCd > 0 || p.dead) return;
  let dx = 0;
  let dy = 0;
  if (G.keys['arrowup'] || G.keys['w']) dy -= 1;
  if (G.keys['arrowdown'] || G.keys['s']) dy += 1;
  if (G.keys['arrowleft'] || G.keys['a']) dx -= 1;
  if (G.keys['arrowright'] || G.keys['d']) dx += 1;
  if (dx === 0 && dy === 0) {
    dx = Math.cos(p.aim);
    dy = Math.sin(p.aim);
  }
  const len = Math.sqrt(dx * dx + dy * dy);
  p.vx = (dx / len) * PLAYER.dashSpeed;
  p.vy = (dy / len) * PLAYER.dashSpeed;
  p.dashT = PLAYER.dashTime;
  p.invulnT = Math.max(p.invulnT, PLAYER.dashIframes);
  G.dashCd = PLAYER.dashCooldown;
  G.audio.dash();
  burst(G.particles, p.x, p.y, COL.cyan, 10, 160, 0.5, 0);
  // Radial knockback pulse: shove nearby enemies away and hurt them.
  for (const e of G.enemies) {
    const d = dist(p.x, p.y, e.x, e.y);
    if (d < PLAYER.dashPulseR + e.r) {
      const a = Math.atan2(e.y - p.y, e.x - p.x);
      e.x += Math.cos(a) * 46;
      e.y += Math.sin(a) * 46;
      damageEnemy(e, PLAYER.dashPulseDmg, null, false);
    }
  }
}

function doConvergence() {
  if (G.resonance < 100 || G.convergenceT > 0 || G.prisms.length < 2) return;
  G.resonance = 0;
  G.convergenceT = 4;
  G.audio.convergence();
  G.shake = Math.max(G.shake, 5);
  G.texts.push(makeFloatText(CX, CY - 90, 'SOLAR CONVERGENCE', COL.magenta, 22));
}

// ---- Boss ----

function updateBoss(dt) {
  const b = G.boss;
  if (!b || b.hp <= 0) return;
  b.t += dt;
  const slow = b.slowUntil > G.time ? PHASES[0].slow : 1;
  b.orbitAngle += BOSS.orbitSpeed * slow * dt;
  if (b.burnUntil > G.time) b.hp -= b.burnDps * dt;
  const segs = bossSegments(b);
  b.x = segs[0].x;
  b.y = segs[0].y;
  b.facing = b.orbitAngle + Math.PI / 2;
  // Solar-flare sweep: telegraph, then a rotating damage sector.
  b.flareIn -= dt;
  if (b.flareState === 0 && b.flareIn <= 0) {
    b.flareState = 1;
    b.flareT = BOSS.flareTelegraph;
    b.flareAngle = Math.atan2(G.player.y - CY, G.player.x - CX);
    G.audio.horn();
  } else if (b.flareState === 1) {
    b.flareT -= dt;
    if (b.flareT <= 0) {
      b.flareState = 2;
      b.flareT = BOSS.flareSweep;
    }
  } else if (b.flareState === 2) {
    b.flareT -= dt;
    b.flareAngle += 1.1 * dt;
    const p = G.player;
    if (!p.dead) {
      const pa = Math.atan2(p.y - CY, p.x - CX);
      const pd = dist(p.x, p.y, CX, CY);
      if (pd > 70 && Math.abs(angleDiff(pa, b.flareAngle)) < 0.32) hurtPlayer(22);
    }
    if (b.flareT <= 0) {
      b.flareState = 0;
      b.flareIn = BOSS.flareEvery;
    }
  }
  // Minion spawns from the serpent's head.
  b.spawnIn -= dt;
  if (b.spawnIn <= 0) {
    b.spawnIn = BOSS.spawnEvery;
    for (let i = 0; i < 3; i++) {
      G.enemies.push(makeEnemy('mote', b.x + rand(-40, 40), b.y + rand(-40, 40)));
    }
  }
  if (b.hp <= 0) {
    b.hp = 0;
    G.hitStop = 0.09;
    G.shake = 14;
    burst(G.particles, b.x, b.y, COL.danger, 50, 380, 1.6, 1);
    burst(G.particles, b.x, b.y, COL.amber, 40, 300, 1.4, 2);
    G.cyclesCleared = 5;
    endRun(true);
  }
}

// A point hit against the boss: nodes first (they are the weak points),
// then the serpent's body. Returns true when something was hit.
function hitBoss(x, y, dmg, fromAngle) {
  const b = G.boss;
  if (!b || b.hp <= 0) return false;
  const segs = bossSegments(b);
  for (const n of b.nodes) {
    if (n.dead) continue;
    const s = segs[n.seg];
    if (dist(x, y, s.x, s.y) < 16) {
      n.hp -= dmg;
      if (n.hp <= 0) {
        n.dead = true;
        b.hp -= BOSS.nodeDmg;
        G.hitStop = 0.025; // 25ms hit-stop on node destruction
        G.shake = Math.max(G.shake, 10);
        G.score += 500 * G.multiplier;
        G.audio.shatter();
        burst(G.particles, s.x, s.y, '#ffd76a', 26, 320, 1, 1);
        G.texts.push(makeFloatText(s.x, s.y - 20, 'NODE SHATTERED', '#ffd76a', 17));
        if (b.hp <= 0) updateBoss(0);
      }
      return true;
    }
  }
  for (const s of segs) {
    if (dist(x, y, s.x, s.y) < s.r) {
      b.hp -= dmg;
      b.flash = 1;
      return true;
    }
  }
  return false;
}

// ---- Update ----

function update(dt) {
  G.time += dt;
  const p = G.player;
  if (G.bannerT > 0) G.bannerT -= dt;
  if (G.chimeCd > 0) G.chimeCd -= dt;
  G.shake = Math.max(0, G.shake - dt * 26);
  if (G.dashCd > 0) G.dashCd -= dt;
  if (G.dashT > 0) G.dashT -= dt;
  if (p.invulnT > 0) p.invulnT -= dt;

  // Player respawn.
  if (p.dead) {
    p.respawnT -= dt;
    if (p.respawnT <= 0) {
      p.dead = false;
      p.hull = PLAYER.hullMax;
      p.x = CX;
      p.y = CY + 140;
      p.vx = 0;
      p.vy = 0;
      p.invulnT = 1.2;
    }
  }

  // Movement: WASD / arrows with inertia.
  if (!p.dead) {
    let ax = 0;
    let ay = 0;
    if (G.keys['arrowup'] || G.keys['w']) ay -= 1;
    if (G.keys['arrowdown'] || G.keys['s']) ay += 1;
    if (G.keys['arrowleft'] || G.keys['a']) ax -= 1;
    if (G.keys['arrowright'] || G.keys['d']) ax += 1;
    if (ax !== 0 || ay !== 0) {
      const len = Math.sqrt(ax * ax + ay * ay);
      p.vx += (ax / len) * PLAYER.accel * dt;
      p.vy += (ay / len) * PLAYER.accel * dt;
    }
    const damp = Math.exp(-PLAYER.damping * dt);
    p.vx *= damp;
    p.vy *= damp;
    const sp = Math.sqrt(p.vx * p.vx + p.vy * p.vy);
    if (sp > PLAYER.maxSpeed && G.dashT <= 0) {
      p.vx = (p.vx / sp) * PLAYER.maxSpeed;
      p.vy = (p.vy / sp) * PLAYER.maxSpeed;
    }
    p.x = clamp(p.x + p.vx * dt, 24, W - 24);
    p.y = clamp(p.y + p.vy * dt, 24, H - 24);
    p.aim = Math.atan2(G.mouse.y - p.y, G.mouse.x - p.x);
    if (G.time - p.lastHurt > 3 && p.hull < PLAYER.hullMax) {
      p.hull = Math.min(PLAYER.hullMax, p.hull + PLAYER.hullRegen * dt);
    }
  }

  // Firing: a tap fires a Solar Bolt; holding past 0.18s channels the beam.
  G.beaming = false;
  if (G.mouse.left && !p.dead) {
    G.beamHoldT += dt;
    if (G.beamHoldT > 0.18 && G.energy > 1) {
      G.beaming = true;
      G.energy = Math.max(0, G.energy - PLAYER.beamDrain * dt);
      G.audio.beamStart();
    }
  } else {
    G.beamHoldT = 0;
    G.audio.beamStop();
  }
  if (!G.beaming) {
    G.energy = Math.min(PLAYER.energyMax, G.energy + PLAYER.energyRecharge * dt);
    G.beamSegs = [];
  } else {
    const segs = traceBeam(G.prisms, p.x, p.y, p.aim, 0, [], []);
    G.beamSegs = segs;
    let prismTouched = false;
    for (const s of segs) {
      if (s.depth > 0) prismTouched = true;
      damageBeamSegment(s, G.enemies, PLAYER.beamDps, dt, function (e, phase, dmg) {
        damageEnemy(e, dmg, null, s.depth > 0);
        applyChromatic(e, phase, G.time);
      });
      // The beam also bites the boss and its nodes.
      const b = G.boss;
      if (b && b.hp > 0) {
        if (segDist(b.x, b.y, s.x1, s.y1, s.x2, s.y2) < 40) {
          b.hp -= PLAYER.beamDps * dt;
          applyChromatic(b, s.phase, G.time);
        }
      }
    }
    if (prismTouched && G.chimeCd <= 0) {
      G.audio.chime(G.combo);
      G.chimeCd = 0.3;
    }
  }

  // Convergence web: every edge between prisms burns what it touches.
  if (G.convergenceT > 0) {
    G.convergenceT -= dt;
    const ps = G.prisms;
    for (let i = 0; i < ps.length; i++) {
      for (let j = i + 1; j < ps.length; j++) {
        for (const e of G.enemies) {
          if (e.hp > 0 && segDist(e.x, e.y, ps[i].x, ps[i].y, ps[j].x, ps[j].y) < e.r + 10) {
            damageEnemy(e, 130 * dt, null, true);
          }
        }
      }
    }
  }

  // Spawn queue.
  if (G.queue.length > 0) {
    G.queue[0].at -= dt;
    while (G.queue.length > 0 && G.queue[0].at <= 0) {
      const s = G.queue.shift();
      const pos = edgeSpawn();
      G.enemies.push(makeEnemy(s.kind, pos.x, pos.y));
    }
  }

  // Enemies.
  for (const e of G.enemies) updateEnemy(e, dt, G.time, G.orbs, CX, CY);
  updateBoss(dt);

  // Bolts.
  for (let i = G.bolts.length - 1; i >= 0; i--) {
    const b = G.bolts[i];
    b.x += b.vx * dt;
    b.y += b.vy * dt;
    b.life -= dt;
    let dead = b.life <= 0 || b.x < 0 || b.x > W || b.y < 0 || b.y > H;
    if (!dead) {
      for (const e of G.enemies) {
        if (e.hp > 0 && dist(b.x, b.y, e.x, e.y) < e.r + 4) {
          G.shotsHit += 1;
          damageEnemy(e, PLAYER.boltDmg, Math.atan2(b.vy, b.vx), false);
          G.audio.hit();
          dead = true;
          break;
        }
      }
    }
    if (!dead && hitBoss(b.x, b.y, PLAYER.boltDmg, Math.atan2(b.vy, b.vx))) {
      G.shotsHit += 1;
      dead = true;
    }
    if (dead) G.bolts.splice(i, 1);
  }

  // Enemy orbs.
  for (let i = G.orbs.length - 1; i >= 0; i--) {
    const o = G.orbs[i];
    o.x += o.vx * dt;
    o.y += o.vy * dt;
    o.life -= dt;
    let dead = o.life <= 0;
    if (!dead && dist(o.x, o.y, CX, CY) < CORE_R + o.r) {
      hurtCore(5, o.x, o.y);
      dead = true;
    }
    if (!dead && !p.dead && dist(o.x, o.y, p.x, p.y) < p.r + o.r) {
      hurtPlayer(10);
      dead = true;
    }
    if (dead) G.orbs.splice(i, 1);
  }

  // Enemies reaching the core, or ramming the player.
  for (let i = G.enemies.length - 1; i >= 0; i--) {
    const e = G.enemies[i];
    if (e.hp <= 0) {
      G.enemies.splice(i, 1);
      continue;
    }
    if (dist(e.x, e.y, CX, CY) < CORE_R + e.r) {
      hurtCore(e.coreDmg, e.x, e.y);
      G.enemies.splice(i, 1);
      continue;
    }
    if (!p.dead && dist(e.x, e.y, p.x, p.y) < e.r + p.r) {
      if (p.dashT > 0) {
        const a = Math.atan2(e.y - p.y, e.x - p.x);
        e.x += Math.cos(a) * 30;
        e.y += Math.sin(a) * 30;
        damageEnemy(e, PLAYER.dashPulseDmg, null, false);
      } else {
        hurtPlayer(8);
        damageEnemy(e, 12, null, false);
        const a = Math.atan2(e.y - p.y, e.x - p.x);
        e.x += Math.cos(a) * 18;
        e.y += Math.sin(a) * 18;
      }
    }
  }

  // Particles and floating text.
  for (let i = G.particles.length - 1; i >= 0; i--) {
    const pt = G.particles[i];
    pt.life -= dt;
    pt.x += pt.vx * dt;
    pt.y += pt.vy * dt;
    pt.vx *= 0.98;
    pt.vy *= 0.98;
    pt.rot += pt.vr * dt;
    if (pt.life <= 0) G.particles.splice(i, 1);
  }
  for (let i = G.texts.length - 1; i >= 0; i--) {
    const t = G.texts[i];
    t.life -= dt;
    t.y -= 34 * dt;
    if (t.life <= 0) G.texts.splice(i, 1);
  }
  for (const pr of G.prisms) {
    pr.angle += dt * 0.4;
    if (pr.flash > 0) pr.flash = Math.max(0, pr.flash - dt * 2.5);
  }

  // Cycle cleared? Brief intermission, then the next Astral Cycle.
  if (G.state === 'play' && G.intermissionT <= 0 && cycleCleared(G.queue, G.enemies, G.boss)) {
    if (G.cycle < 4) {
      G.intermissionT = 3;
      G.banner = 'Cycle Cleared — the weave holds';
      G.bannerT = 2.6;
    }
  }
  if (G.intermissionT > 0) {
    G.intermissionT -= dt;
    if (G.intermissionT <= 0) nextCycle();
  }
}

// ---- Screenshot mode (deterministic renders for the entry) ----

// A simple scripted pilot so ?shot= renders show real gameplay, not an
// empty arena: aim at the nearest enemy, fire bolts, channel the beam
// through the prisms, and dash when the cooldown is ready.
function autoPilot(dt) {
  const p = G.player;
  let best = null;
  let bestD = Infinity;
  for (const e of G.enemies) {
    const d = dist(p.x, p.y, e.x, e.y);
    if (d < bestD) {
      bestD = d;
      best = e;
    }
  }
  const target = best || G.boss;
  if (target) {
    G.mouse.x = target.x;
    G.mouse.y = target.y;
    p.aim = Math.atan2(target.y - p.y, target.x - p.x);
    // Strafe in a slow circle so the ship is never static.
    const a = G.time * 0.7;
    G.keys['w'] = Math.sin(a) > 0.3;
    G.keys['s'] = Math.sin(a) < -0.3;
    G.keys['a'] = Math.cos(a) < -0.3;
    G.keys['d'] = Math.cos(a) > 0.3;
    // Alternate: bolt volleys, then a held beam through the prisms.
    if (Math.floor(G.time * 2) % 2 === 0) {
      G.mouse.left = true;
      G.beamHoldT = 0.3; // already past the tap threshold: beam channels
    } else {
      G.mouse.left = false;
      G.beamHoldT = 0;
      if (G.shotsFired < Math.floor(G.time * 5)) fireBolt();
    }
    if (G.dashCd <= 0 && bestD < 140) doDash();
  }
}

function simulate(seconds) {
  const step = 1 / 60;
  const n = Math.round(seconds / step);
  for (let i = 0; i < n; i++) {
    autoPilot(step);
    update(step);
    if (G.state !== 'play') break;
  }
  G.mouse.left = false;
  G.beaming = false;
  G.beamSegs = G.prisms.length ? traceBeam(G.prisms, G.player.x, G.player.y, G.player.aim, 0, [], []) : [];
}

function setupShot(shot) {
  if (shot === 'title') {
    G.state = 'title';
  } else if (shot === 'play') {
    startRun();
    placePrism(G.prisms, CX - 160, CY - 80, 0);
    G.prismsPlaced = 1;
    simulate(5);
  } else if (shot === 'intense') {
    // The boss fight: Cycle V, the Eclipse Leviathan on its orbit with its
    // minions, three prisms live and a beam mid-channel — the busiest frame.
    startRun();
    startCycle(4);
    placePrism(G.prisms, CX - 170, CY - 90, 0);
    placePrism(G.prisms, CX + 150, CY - 110, 1);
    placePrism(G.prisms, CX + 40, CY + 170, 2);
    G.prismsPlaced = 3;
    simulate(11);
    G.combo = 14;
    G.multiplier = 4;
    G.resonance = 64;
    // Keep a beam visibly live in the frozen frame, aimed at the Leviathan.
    if (G.boss && G.boss.hp > 0) {
      G.player.aim = Math.atan2(G.boss.y - G.player.y, G.boss.x - G.player.x);
      G.beamSegs = traceBeam(G.prisms, G.player.x, G.player.y, G.player.aim, 0, [], []);
    }
  } else if (shot === 'gameover') {
    startRun();
    placePrism(G.prisms, CX - 160, CY - 80, 0);
    simulate(7);
    G.score = 12480;
    G.maxCombo = 23;
    G.maxMultiplier = 6;
    G.ricochetKills = 41;
    G.shotsFired = 120;
    G.shotsHit = 86;
    G.cyclesCleared = 3;
    G.prismsPlaced = 9;
    G.coreHp = 0;
    endRun(false);
  } else {
    return;
  }
  G.frozen = true;
}

// ---- Main loop ----

let lastT = 0;
function frame(ts) {
  requestAnimationFrame(frame);
  const now = ts / 1000;
  let dt = Math.min(0.033, now - (lastT || now));
  lastT = now;
  if (G.frozen) {
    drawGame(ctx, G);
    return;
  }
  if (G.hitStop > 0) {
    G.hitStop -= dt;
    drawGame(ctx, G);
    return;
  }
  if (G.state === 'play') update(dt);
  else G.time += dt; // menus keep their slow ambient motion
  drawGame(ctx, G);
}

// ---- Input ----

function bindInput() {
  window.addEventListener('keydown', function (e) {
    const k = e.key.toLowerCase();
    if (['arrowup', 'arrowdown', 'arrowleft', 'arrowright', ' '].indexOf(k) !== -1) e.preventDefault();
    G.audio.unlock();
    if (k === 'm') {
      G.audio.setMuted(!G.audio.muted);
      return;
    }
    if (k === 'p' || k === 'escape') {
      if (G.state === 'play') G.state = 'paused';
      else if (G.state === 'paused') G.state = 'play';
      return;
    }
    if (k === 'enter') {
      if (G.state === 'title' || G.state === 'victory' || G.state === 'over') startRun();
      return;
    }
    if (k === ' ' || k === 'shift') {
      if (G.state === 'play') doDash();
      return;
    }
    if (k === 'q') {
      if (G.state === 'play') doConvergence();
      return;
    }
    if (k === 'e') {
      if (G.state === 'play') {
        placePrism(G.prisms, G.mouse.x, G.mouse.y, G.time);
        G.prismsPlaced += 1;
        G.audio.chime(2);
      }
      return;
    }
    if (k === 'r' && (G.state === 'paused' || G.state === 'over' || G.state === 'victory')) {
      startRun();
      return;
    }
    G.keys[k] = true;
  });
  window.addEventListener('keyup', function (e) {
    G.keys[e.key.toLowerCase()] = false;
  });
  window.addEventListener('blur', function () {
    G.keys = {};
    G.mouse.left = false;
  });

  function mousePos(e) {
    const r = canvas.getBoundingClientRect();
    return {
      x: ((e.clientX - r.left) / r.width) * W,
      y: ((e.clientY - r.top) / r.height) * H,
    };
  }
  canvas.addEventListener('mousemove', function (e) {
    const m = mousePos(e);
    G.mouse.x = m.x;
    G.mouse.y = m.y;
  });
  canvas.addEventListener('mousedown', function (e) {
    G.audio.unlock();
    const m = mousePos(e);
    G.mouse.x = m.x;
    G.mouse.y = m.y;
    if (G.state === 'title' || G.state === 'victory' || G.state === 'over') {
      startRun();
      return;
    }
    if (G.state !== 'play') return;
    if (e.button === 2) {
      placePrism(G.prisms, m.x, m.y, G.time);
      G.prismsPlaced += 1;
      G.audio.chime(2);
    } else if (e.button === 0) {
      G.mouse.left = true;
      G.mouse.pressT = G.time;
      G.beamHoldT = 0;
      fireBolt();
    }
  });
  window.addEventListener('mouseup', function (e) {
    if (e.button === 0) {
      G.mouse.left = false;
      G.beamHoldT = 0;
    }
  });
  canvas.addEventListener('contextmenu', function (e) {
    e.preventDefault();
  });
}

// ---- Boot ----

function boot() {
  canvas = document.getElementById('game');
  ctx = canvas.getContext('2d');
  const params = new URLSearchParams(window.location.search);
  const seed = parseInt(params.get('seed') || '0', 10);
  rng = mulberry32(seed || (Date.now() % 2147483647));
  bindInput();
  // Read-only debug handle for automated play-testing (state, never control).
  window.__lumenweave = {
    snapshot: function () {
      return {
        state: G.state,
        score: G.score,
        combo: G.combo,
        coreHp: G.coreHp,
        energy: Math.round(G.energy),
        cycle: G.cycle,
        enemies: G.enemies.length,
        prisms: G.prisms.length,
        bossHp: G.boss ? G.boss.hp : null,
        resonance: Math.round(G.resonance),
        shotsFired: G.shotsFired,
      };
    },
  };
  const shot = params.get('shot');
  if (shot) setupShot(shot);
  requestAnimationFrame(frame);
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', boot);
} else {
  boot();
}


})();
